1763		// 9: a health report under the OLD revision conflicts even though its
1764		// sequence 99 exceeds anything accepted before; it names both revisions and
1765		// must not heal the new address.
1766		if r := got.Results[9]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1767			r.ExpectedRevision != 1 || r.ActualRevision != 2 || r.Revision != 2 {
1768			t.Fatalf("old-revision health report: %+v", r)
1769		}
1770		// 10: with a unknown (the conflicting report healed nothing) and b, c
1771		// unhealthy, the session request is no_healthy: it states the reason and
1772		// the current revision and fabricates neither an instance id nor an
1773		// address. The failure must not rewrite the s -> a binding or move the
1774		// cursor off b.
1775		if r := got.Results[10]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
1776			r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
