1778		}
1779		// 11: a fresh observation at the current revision heals the new address;
1780		// the sequence restarts at 1, below the 11 accepted for the old address.
1781		if r := got.Results[11]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 1 {
1782			t.Fatalf("fresh observation at new address: %+v", r)
1783		}
1784		// 12: the binding survived the no_healthy failure, so the session reuses a
1785		// again — with its CURRENT address and sequence, and without rotating.
1786		if r := got.Results[12]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 2 {
1787			t.Fatalf("session should reuse a after its recovery: %+v", r)
1788		}
1789		// 13-14: b and c recover at the current revision.
1790		if r := got.Results[13]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 16 {
1791			t.Fatalf("b recovery: %+v", r)
1792		}
1793		if r := got.Results[14]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 17 {
1794			t.Fatalf("c recovery: %+v", r)
1795		}
1796		// 15: the no_healthy failure never moved the cursor off b and the session
1797		// reuse did not rotate either, so the plain select continues just after b
1798		// and lands on c.
1799		if r := got.Results[15]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 17 || r.Revision != 2 {
1800			t.Fatalf("plain select should resume after b at c: %+v", r)
1801		}
1802		// The final list reflects the new address and only the accepted health
1803		// records: a healthy at h9:9 with the restarted sequence 1, b and c
1804		// healthy again with their recovery sequences and no leftover reason.
1805		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
1806			t.Fatalf("services: %+v", got.Services)
1807		}
1808		insts := got.Services[0].Instances
1809		if len(insts) != 3 {
1810			t.Fatalf("instances: %+v", insts)
1811		}
1812		wantInsts := []registerInstance{
1813			{ID: "a", Address: "h9:9", Health: "healthy", Sequence: 1},
1814			{ID: "b", Address: "h2:2", Health: "healthy", Sequence: 16},
1815			{ID: "c", Address: "h3:3", Health: "healthy", Sequence: 17},
1816		}
1817		for i, want := range wantInsts {
1818			if insts[i] != want {
1819				t.Fatalf("instance %d: got %+v want %+v", i, insts[i], want)
1820			}
1821		}
