		"blank string":  `{"requests":[{"type":"select","service":"s","expectedRevision":0,"sessionKey":"   "}]}`,
		"empty string":  `{"requests":[{"type":"select","service":"s","expectedRevision":0,"sessionKey":""}]}`,
