// maxRevision is the largest expectedRevision accepted on the running
// architecture. Revisions are carried by int, so a 32-bit build accepts
// 0..2147483647 and a 64-bit build 0..9223372036854775807. A value outside
// that range must be rejected from its raw submitted form; otherwise it wraps
// when narrowed to int (e.g. 4294967297 becoming 1 on a 32-bit build) and
// could match a revision it never equalled.
const maxRevision = math.MaxInt

// validateExpectedRevision is the revision field shared by every request: it
// must be a non-negative integer no larger than the running architecture's int
// maximum (2147483647 on 32-bit, 9223372036854775807 on 64-bit). Callers check
// their remaining content fields after this one, so content validity is fully
// established before any revision comparison against the registry.
func validateExpectedRevision(revision int) error {
	if revision < 0 || revision > maxRevision {
		return errInvalid(fmt.Sprintf(
			"expectedRevision must be an integer between 0 and %d, got %d",
			maxRevision, revision))
	}
	return nil
}

// CheckExpectedRevision validates a raw submitted expectedRevision before it is
// narrowed to int. The command layer decodes JSON numbers into int64, which on a
// 32-bit build still holds values outside int's range; converting those first
// would silently wrap them (4294967297 to 1, -4294967295 to 1) and make a
// mismatching revision look current. The raw value — not the wrapped one — is
// therefore range-checked here: negatives and integers above the platform's int
// maximum are invalid, with the reason stating the expectedRevision range.
// JSON numbers that do not fit int64 (including very large magnitudes) are
// rejected by the decoder before this point.
func CheckExpectedRevision(revision int64) (int, error) {
	if revision < 0 || revision > maxRevision {
		return 0, errInvalid(fmt.Sprintf(
			"expectedRevision must be an integer between 0 and %d, got %d",
			maxRevision, revision))
	}
	return int(revision), nil
}

