// ParseExpectedRevision converts the raw decimal text of a submitted
// expectedRevision into an integer that still carries the submitted value. It
// only establishes that the token is a decimal integer fitting int64; the
// platform-specific range (the 32-bit upper bound in particular) is enforced
// afterwards by validateExpectedRevision, which runs in each Validate* method
// alongside the other field checks. Splitting the two keeps the registry's
// field-check ordering intact while letting the command layer judge the raw
// token — including magnitudes too large for int64, which ParseInt rejects
// with ErrRange and which are reported from their raw text rather than an
// overflowed number. Non-integer text (floats, strings, booleans, null) gets
// the integer-type error.
func ParseExpectedRevision(text string) (int64, error) {
	n, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		if errors.Is(err, strconv.ErrRange) {
			return 0, errInvalid(expectedRevisionRangeReason(text))
		}
		return 0, errInvalid(fmt.Sprintf("expectedRevision must be an integer, got %s", text))
	}
	return n, nil
}

