// TestRegisterOutOfRangeFieldPrecedence locks that the range is judged as a
// field, ahead of the revision conflict, in the same positions as the old
// non-negative check, while fields checked earlier still win.
func TestRegisterOutOfRangeFieldPrecedence(t *testing.T) {
	out, code := runRegisterWith(t, `{"requests":[
		{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
		{"type":"register","service":"  ","expectedRevision":`+hugeRevisionJSON+`,"instances":[]},
		{"type":"register","service":"svc","expectedRevision":`+hugeRevisionJSON+`,"instances":[{"id":"","address":"h1:8080"}]},
		{"type":"health","service":"svc","instanceId":" ","expectedRevision":`+hugeRevisionJSON+`,"sequence":1,"healthy":true},
		{"type":"health","service":"svc","instanceId":"i1","expectedRevision":`+hugeRevisionJSON+`,"sequence":0,"healthy":true},
		{"type":"select","service":"  ","expectedRevision":`+hugeRevisionJSON+`},
		{"type":"select","service":"svc","expectedRevision":`+hugeRevisionJSON+`,"sessionKey":null}
	]}`)
	if code != 1 {
		t.Fatalf("exit code: %d", code)
	}
	got := decodeRegisterOutput(t, out)
	want := []string{
		"", // 0 valid
		"service name must not be empty",
		"expectedRevision must be an integer between 0 and",
		"instance id must not be empty",
		"expectedRevision must be an integer between 0 and",
		"service name must not be empty",
		"sessionKey must be a string, not null",
	}
	for i, sub := range want {
		if sub == "" {
			continue
		}
		r := got.Results[i]
		if r.OK || r.Error != "invalid" {
			t.Fatalf("result %d: want invalid, got %+v", i, r)
		}
		if !strings.Contains(r.Reason, sub) {
			t.Fatalf("result %d reason %q should contain %q", i, r.Reason, sub)
		}
		if r.ExpectedRevision != 0 || r.ActualRevision != 0 {
			t.Fatalf("result %d must not be a conflict: %+v", i, r)
		}
	}
}

// TestRegisterLargeInRangeRevisionOn64Bit locks that the fix does not clamp
// 64-bit builds to the 32-bit bound: 2147483648 is a legal integer on 64-bit
// and yields an ordinary conflict against a revision-1 service while
// preserving the submitted value. On 32-bit it is rejected as out of range.
func TestRegisterLargeInRangeRevisionOn64Bit(t *testing.T) {
	const large = "2147483648"
	input := `{"requests":[
		{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
		{"type":"register","service":"svc","expectedRevision":` + large + `,"instances":[]},
		{"type":"select","service":"svc","expectedRevision":` + large + `}
	]}`
	out, code := runRegisterWith(t, input)
	if code != 1 {
		t.Fatalf("exit code: %d", code)
	}
	got := decodeRegisterOutput(t, out)
	if strconv.IntSize == 32 {
		assertRangeInvalid(t, got.Results[1], 1, large)
		assertRangeInvalid(t, got.Results[2], 1, large)
		return
	}
	for i := 1; i <= 2; i++ {
		r := got.Results[i]
		if r.OK || r.Error != "conflict" ||
			r.ExpectedRevision != 2147483648 || r.ActualRevision != 1 || r.Revision != 1 {
			t.Fatalf("result %d should be a normal conflict preserving %s: %+v", i, large, r)
		}
	}
}

